fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // k is 1-based indexing. So, the element to remove has 0-based index k-1.
    let remove_index = k - 1;

    // Create a new vector with capacity n - 1
    let mut new_list = Vec::with_capacity(list.len() - 1);

    // Extend with elements before the removed index (0 up to k-2)
    new_list.extend_from_slice(&list[0..remove_index]);

    // Extend with elements after the removed index (k to end)
    new_list.extend_from_slice(&list[remove_index + 1..]);

    new_list
}